// ─── MODO PRUEBA ──────────────────────────────────────────────────────────
// El inbox de Chatwoot se comparte con el bot del lubricentro y con el de
// Gianni. Sin este filtro contestan los tres a la vez sobre la misma
// conversación. Poné acá tu número de prueba: SOLO DÍGITOS, con código de país.
//
//   const SOLO_ESTOS_NUMEROS = ['5492214412200'];
//
// Lista vacía = atiende a todos. Cuando el complejo tenga su propio número,
// vaciala. Y acordate de la mitad simétrica: los otros workflows tienen que
// EXCLUIR estos mismos números, si no te siguen contestando en paralelo.
const SOLO_ESTOS_NUMEROS = [];

// Aplana el payload de Chatwoot de forma defensiva (soporta wrap en body).
const p = ($json && $json.body) ? $json.body : ($json || {});
const event = p.event || '';
const mt = p.message_type;
const isIncoming = (mt === 'incoming' || mt === 0 || mt === '0');
const conv = p.conversation || {};
const meta = conv.meta || {};
const sender = p.sender || meta.sender || {};

let attachments = p.attachments || [];
if ((!attachments || !attachments.length) && Array.isArray(p.messages) && p.messages[0]) {
  attachments = p.messages[0].attachments || [];
}
const audioAtt = (attachments || []).find(a => a && (a.file_type === 'audio' || a.file_type === 'voice'));
// El comprobante de la seña llega como imagen (captura del banco) o PDF.
const docAtt = (attachments || []).find(a => a && (a.file_type === 'image' || a.file_type === 'file'));

const phoneRaw = sender.phone_number || sender.identifier || '';
const phoneNumber = String(phoneRaw).replace(/\D/g, '');

let type = 'text';
if (audioAtt) type = 'audio';
else if (docAtt) type = 'archivo';

// El código de reserva se extrae con una expresión regular y NO se le pregunta
// al modelo. Es el vínculo entre la reserva de la web y este chat: si depende
// de que el modelo lo lea bien, un día cobra la seña del turno equivocado.
// El alfabeto no tiene O ni I ni 0 ni 1 (se confunden al dictarlos).
const texto = String(p.content || '');
const mCod = texto.match(/#\s?([A-HJ-NP-Z2-9]{6})\b/i);
const codigoReserva = mCod ? mCod[1].toUpperCase() : '';

// Mime y tamaño hacen falta ANTES de bajar el archivo: la Edge Function los
// valida antes de firmar la subida, así que un archivo que no corresponde ni
// se descarga de Chatwoot.
let archivoMime = '';
if (docAtt) {
  archivoMime = docAtt.content_type
    || (docAtt.file_type === 'image' ? 'image/jpeg' : 'application/pdf');
}

const numeroHabilitado =
  SOLO_ESTOS_NUMEROS.length === 0 || SOLO_ESTOS_NUMEROS.indexOf(phoneNumber) !== -1;

return [{ json: {
  event: event,
  isIncoming: isIncoming,
  isMessageCreated: event === 'message_created',
  numeroHabilitado: numeroHabilitado,
  proceed: (event === 'message_created' && isIncoming && numeroHabilitado),
  type: type,
  content: texto,
  codigoReserva: codigoReserva,
  audioUrl: audioAtt ? (audioAtt.data_url || '') : '',
  archivoUrl: docAtt ? (docAtt.data_url || '') : '',
  archivoMime: archivoMime,
  archivoTamano: docAtt ? (docAtt.file_size || 0) : 0,
  phoneNumber: phoneNumber,
  pushName: sender.name || 'Jugador',
  conversationId: (conv.id != null ? conv.id : (p.conversation_id != null ? p.conversation_id : '')),
  accountId: (p.account && p.account.id != null ? p.account.id : ''),
  messageId: (p.id != null ? p.id : '')
} }];

const norm = $('Normalizar Entrada').first().json;

let contexto = {};
try { contexto = $('Estado de Sesion').first().json || {}; } catch (e) { contexto = {}; }

// ─── La fecha se calcula ACÁ y no se toma de la API ────────────────────────
// Un modelo de lenguaje sin fecha explícita no dice "no sé qué día es": usa la
// de su entrenamiento. Es exactamente así como una consulta por "hoy a las 14"
// terminó buscando disponibilidad para abril de 2024.
//
// Este bloque corre siempre, aunque la Edge Function esté caída o la
// credencial esté mal: es JavaScript local, no depende de ninguna red.
const TZ = 'America/Argentina/Cordoba';
const ahora = new Date();
const hoy = new Intl.DateTimeFormat('en-CA', { timeZone: TZ }).format(ahora);
const horaActual = new Intl.DateTimeFormat('es-AR', {
  timeZone: TZ, hour: '2-digit', minute: '2-digit', hour12: false
}).format(ahora);

const DIAS = ['domingo','lunes','martes','miércoles','jueves','viernes','sábado'];
const MESES = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];

// Fecha civil como números, sin pasar por Date: '2026-08-06' interpretado como
// Date da el día anterior en Argentina, y ese corrimiento en un bot de reservas
// significa mandar a alguien a la cancha el día equivocado.
const [aa, mm, dd] = hoy.split('-').map(Number);
const diaSemana = DIAS[new Date(Date.UTC(aa, mm - 1, dd)).getUTCDay()];

const sumar = (n) => {
  const d = new Date(Date.UTC(aa, mm - 1, dd + n));
  return d.toISOString().slice(0, 10);
};

// Los próximos 7 días con nombre, para que traducir "el sábado" sea buscar en
// una lista y no hacer aritmética de calendario.
const proximos = [];
for (let i = 0; i <= 7; i++) {
  const iso = sumar(i);
  const [y, m, d] = iso.split('-').map(Number);
  const nombre = DIAS[new Date(Date.UTC(y, m - 1, d)).getUTCDay()];
  const etiqueta = i === 0 ? 'hoy' : i === 1 ? 'mañana' : i === 2 ? 'pasado mañana' : nombre;
  proximos.push(etiqueta + ' = ' + iso + ' (' + nombre + ' ' + d + ')');
}

const hoyTexto = 'Hoy es ' + diaSemana + ' ' + dd + ' de ' + MESES[mm - 1] + ' de ' + aa
  + ' (' + hoy + '), y son las ' + horaActual + ' en Argentina.\n'
  + 'Equivalencias de los próximos días:\n  ' + proximos.join('\n  ');

let userMessage = '';

if (norm.type === 'text') {
  userMessage = norm.content || '';

} else if (norm.type === 'audio') {
  try {
    userMessage = $('Transcribir con Whisper').first().json.text || '[Audio no transcrito]';
  } catch (e) {
    userMessage = '[Error al transcribir audio]';
  }

} else if (norm.type === 'archivo') {
  // Acá ya pasó todo: se resolvió el turno, se bajó el archivo de Chatwoot, se
  // subió a Storage y la Edge Function decidió qué hacer. El agente NO ve la
  // imagen: recibe el resultado y una instrucción de qué contestar.
  let r = {};
  try { r = $('Confirmar Reserva').first().json || {}; } catch (e) { r = {}; }

  if (r.ok && r.estado === 'reservado' && r.yaConfirmado) {
    userMessage = '[Sistema] Ese comprobante ya lo habiamos recibido y el turno ya esta confirmado. '
      + 'Decíselo en una línea, sin pedirle que lo reenvíe y sin volver a pedirle la seña.';

  } else if (r.ok && r.estado === 'reservado') {
    const t = r.turno || {};
    userMessage = '[Sistema] Llego el comprobante y el turno quedo CONFIRMADO: '
      + (t.cancha || 'la cancha') + ', ' + (t.fecha || '') + ' a las ' + (t.hora || '') + ' hs'
      + (t.codigo ? ', codigo ' + t.codigo : '') + '. '
      + 'Pagado ' + (t.pagado != null ? t.pagado : 0) + ', saldo ' + (t.saldo != null ? t.saldo : 0) + '. '
      + 'Confirmaselo en dos renglones, recordale el saldo si hay, y aclarale que el complejo '
      + 'verifica el pago. No le pidas nada mas.';

  } else if (r.ok && r.requiereValidacion) {
    userMessage = '[Sistema] Llego el comprobante y quedo guardado, pero este complejo revisa cada '
      + 'pago a mano antes de confirmar. Decile que el complejo lo verifica y le confirma por aca. '
      + 'NO le digas que el turno esta confirmado.';

  } else if (r.codigo === 'slot_tomado_con_pago') {
    userMessage = '[Sistema] El comprobante llego pero el horario se habia vencido y lo tomo otro '
      + 'cliente. Pedile disculpas en una linea, decile que el complejo se comunica para reubicarlo '
      + 'o resolver la sena, y DERIVA. No prometas devolucion de plata.';

  } else if (r.codigo === 'comprobante_duplicado') {
    userMessage = '[Sistema] Ese comprobante ya lo habiamos recibido. Decíselo en una linea y segui.';

  } else {
    userMessage = '[Sistema] Llego un archivo del cliente pero no se pudo procesar. NO le pidas que '
      + 'lo reenvie: decile que el complejo lo verifica y DERIVA.';
  }

  if (norm.content) userMessage += ' El cliente ademas escribio: ' + norm.content;
}

return [{ json: {
  chatInput: userMessage,
  sessionId: norm.phoneNumber,
  phoneNumber: norm.phoneNumber,
  pushName: norm.pushName,
  codigoReserva: norm.codigoReserva,
  hoy: hoy,
  horaActual: horaActual,
  hoyTexto: hoyTexto,
  // El contexto viaja serializado: se interpola tal cual al final del system
  // prompt, así el agente arranca sabiendo quién escribe y qué reservas tiene
  // sin gastar una llamada a una herramienta.
  contexto: JSON.stringify(contexto),
  conversationId: norm.conversationId,
  accountId: norm.accountId,
  messageType: norm.type,
  messageId: norm.messageId,
  timestamp: new Date().toISOString()
} }];
